return {["scripts/items/water_mitts.lua"]={["Path"]="scripts/items/water_mitts.lua",["SHA256"]="80920d8e6495c04cda217f519fb1b57e58b978eed32dd53be549187d23dbf905",["Text"]="-----------------------------------\n-- ID: 14992\n-- Water Mitts\n--  Enchantment: \"Enwater\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local fakeSpell = GetSpell(xi.magic.spell.ENWATER)\n    xi.spells.enhancing.useEnhancingSpell(target, target, fakeSpell)\nend\n\nreturn itemObject\n"},["scripts/items/water_spirit_pact.lua"]={["Path"]="scripts/items/water_spirit_pact.lua",["SHA256"]="8b1abf327e2263f3369b1384039a2a449591ee754d1d69bded169242b4736aa1",["Text"]="-----------------------------------\n-- ID: 4901\n-- Water Spirit Pact\n-- Teaches the summoning magic Water Spirit\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.WATER_SPIRIT)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.WATER_SPIRIT)\nend\n\nreturn itemObject\n"},["scripts/items/water_staff.lua"]={["Path"]="scripts/items/water_staff.lua",["SHA256"]="55baf490bb842d35828a8cf6b66c49be3ca1561ea71c965efbd063f89e77a6a5",["Text"]="-----------------------------------\n-- ID: 17555\n-- Item: Water Staff\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 15, -- guessed\n        basePower      = math.randomInt(12, 16),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/water_tank.lua"]={["Path"]="scripts/items/water_tank.lua",["SHA256"]="7454190d17d15ced9d2a05e1e8b0a5ab5a88081a45ef63607bb601d9758047e8",["Text"]="-----------------------------------\n--  ID: 13683\n--  Water Tank\n--  When used, you will obtain one stack of Distilled Water\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FLASK_OF_DISTILLED_WATER, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/watermelon.lua"]={["Path"]="scripts/items/watermelon.lua",["SHA256"]="9cdb114b5c26b2fb4f4ef9da833af400c8f01d5be6c5af4f86284eed3e1d8e9e",["Text"]="-----------------------------------\n-- ID: 4491\n-- Item: watermelon\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -6\n-- Intelligence 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -6)\n    effect:addMod(xi.mod.INT, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/weavers_belt.lua"]={["Path"]="scripts/items/weavers_belt.lua",["SHA256"]="16d195ce04b8ac61f5c0a4786b3985a121ed733e78c51317eb110559513d036c",["Text"]="-----------------------------------\n-- ID: 15447\n-- Item: Weaver's Belt\n-- Enchantment: Synthesis image support\n-- Duration: 8Min\n-- Clothcraft Skill +3\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.CLOTHCRAFT_IMAGERY) then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.CLOTHCRAFT_IMAGERY, { power = 3, duration = 480, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/wedding_bell.lua"]={["Path"]="scripts/items/wedding_bell.lua",["SHA256"]="aca3d1f54f2d74ebae426110710c932d03dfd1b01603db1fa448dfe710656ce8",["Text"]="-----------------------------------\n-- ID: 4170\n-- Wedding Bell\n-- These bells are used in most Vana'diel weddings.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/wedge_of_chalaimbille.lua"]={["Path"]="scripts/items/wedge_of_chalaimbille.lua",["SHA256"]="1b8c2b660e838d8f76463036df4cc2f5d015c30c60e1a25a04535e8ec6a6c42a",["Text"]="-----------------------------------\n-- ID: 5684\n-- Item: wedge_of_chalaimbille\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health % 6 (cap 40)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 6)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/western_san_doria_gate_glyph.lua"]={["Path"]="scripts/items/western_san_doria_gate_glyph.lua",["SHA256"]="fd34cc50dd3d4c201f8b4672b072656efd9ef048c5dfd949389068bf3fb7d8a6",["Text"]="-----------------------------------\n-- ID: 4191\n-- Western San d'Oria Gate Glyph\n-- Transports the user to the western Southern San d'Oria gate\n-- (near Aravoge, T.K.)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.WEST_SANDY_GLYPH, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/whale_staff.lua"]={["Path"]="scripts/items/whale_staff.lua",["SHA256"]="e89653413a559a5b674a4172f5addd2bc4caf43579b667c101cf8ef862ee188c",["Text"]="-----------------------------------\n-- ID: 17533\n-- Item: Whale Staff\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 8 + utils.clamp(dStat * 3 / 27, 0, 25), -- 0-8% over 54 dINT, approx.\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/whale_staff_+1.lua"]={["Path"]="scripts/items/whale_staff_+1.lua",["SHA256"]="4f8e2c2027827a0848d2e3dd9dd131d0140ab4242c9bb5fb4a5818086aa8b242",["Text"]="-----------------------------------\n-- ID: 17534\n-- Item: Whale Staff +1\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 8 + utils.clamp(dStat * 3 / 27, 0, 25), -- 0-8% over 54 dINT, approx.\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/white_drop.lua"]={["Path"]="scripts/items/white_drop.lua",["SHA256"]="3836b9927048c6aed7808f8fd4aefbbb515bc129e9ed2758ef8048401c2fe861",["Text"]="-----------------------------------\n--  ID: 4264\n--  Item: White Drop\n--  Charisma 5\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.CHR_BOOST, { power = 5, duration = 900, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/white_mage_die.lua"]={["Path"]="scripts/items/white_mage_die.lua",["SHA256"]="d2f0bc56bb344e6cce08fa75897a4cfaf45f00736b4335d196b40fafb98ac1dc",["Text"]="-----------------------------------\n-- ID: 5479\n-- White Mage Die\n-- Teaches the job ability Healer's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.HEALERS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.HEALERS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/white_rarab_cap_+1.lua"]={["Path"]="scripts/items/white_rarab_cap_+1.lua",["SHA256"]="d9c052bd9156880a456aa3140347d7ef2a4c980908abd163eb6f40a10838adcb",["Text"]="-----------------------------------\n-- ID: 25679\n-- White Rarab Cap +1\n--  This Hairpin functions in the same way as the spell Reraise.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 7200\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 1, duration = duration, origin = user })\n    target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.RERAISE)\nend\n\nreturn itemObject\n"},["scripts/items/wild_cookie.lua"]={["Path"]="scripts/items/wild_cookie.lua",["SHA256"]="09e871fcc3072b31c6bf1659ccf02cb00f983531f8e5a3d8130aace002fa6404",["Text"]="-----------------------------------\n-- ID: 4577\n-- Item: wild_cookie\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Aquan killer +12\n-- Silence resistance +12\n-- MP recovered while healing +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AQUAN_KILLER, 12)\n    effect:addMod(xi.mod.SILENCERES, 12)\n    effect:addMod(xi.mod.MPHEAL, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/wild_melon.lua"]={["Path"]="scripts/items/wild_melon.lua",["SHA256"]="59332f1368f86106e08ceede148f4ad6694a9cfe1c5c59c475cd74ce41cbe901",["Text"]="-----------------------------------\n-- ID: 4597\n-- Item: wild_melon\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -6\n-- Intelligence 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -6)\n    effect:addMod(xi.mod.INT, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/wild_onion.lua"]={["Path"]="scripts/items/wild_onion.lua",["SHA256"]="82c15779060202482bb6410fbe6b0d01c5cdfdc9abe7e51dbb456b77339dfb44",["Text"]="-----------------------------------\n-- ID: 4387\n-- Item: wild_onion\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 4\n-- Vitality -6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 4)\n    effect:addMod(xi.mod.VIT, -6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/wild_pineapple.lua"]={[