nction(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/wind_arrow.lua"]={["Path"]="scripts/items/wind_arrow.lua",["SHA256"]="a674246b0c3e67049f8f6e664ad0aa9c16d814c12d37eb5717d739218bfe66fe",["Text"]="-----------------------------------\n-- ID: 18700\n-- Item: Wind Arrow\n-- Additional effect: Wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    -- Unconfirmed power.\n\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = 10 + utils.clamp(dStat, -3, 8) + utils.clamp(math.floor((dStat - 8) / 2), 0, 8),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/wind_card_case.lua"]={["Path"]="scripts/items/wind_card_case.lua",["SHA256"]="1194388f16d38a35eb0abbdd3acb240c55b9bd086fd9521a8d47c8791e354a05",["Text"]="-----------------------------------\n-- ID: 5404\n-- Wind Card Case\n-- When used, you will obtain one stack of Wind Cards\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.WIND_CARD, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/wind_cluster.lua"]={["Path"]="scripts/items/wind_cluster.lua",["SHA256"]="a46d6aca6eb1fe68c817a521b83d00a0962dd8198c5b36fef9a372bdc123b65c",["Text"]="-----------------------------------\n-- ID: 4106\n-- Wind Cluster\n-- Turn into a stack of wind crystals\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.WIND_CRYSTAL, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/wind_knife_+1.lua"]={["Path"]="scripts/items/wind_knife_+1.lua",["SHA256"]="6a8e302d5d11f343cb9841f14c5acf7c075036adc082a9f4034598130d50768a",["Text"]="-----------------------------------\n-- ID: 20568\n-- wind_knife_+1\n-- Enchantment: Casts Aero\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(user, target)\n    -- user:castSpell(xi.magic.spell.AERO, target)\n    user:printToPlayer('Wind Knife +1 : enchantment implementation untested.')\nend\n\nreturn itemObject\n"},["scripts/items/wind_spear.lua"]={["Path"]="scripts/items/wind_spear.lua",["SHA256"]="9b8c11f45a4ed29ad8fa04868a8e7ad3a0291a84fc459ea54eea453eed96046a",["Text"]="-----------------------------------\n-- ID: 16857\n-- Item: Wind Spear\n-- Additional effect: wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(18, 25),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WIND,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/wind_staff.lua"]={["Path"]="scripts/items/wind_staff.lua",["SHA256"]="419ea6fede7ccbd9e1ba499be1fc7959baf2939a4b2712f2909464f5afc1b5ca",["Text"]="-----------------------------------\n-- ID: 17549\n-- Item: Wind Staff\n-- Additional effect: wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 25, -- guessed\n        basePower      = math.randomInt(25, 34),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WIND,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/windstorm_schema.lua"]={["Path"]="scripts/items/windstorm_schema.lua",["SHA256"]="806afa41fc3de39c9627e6b2464137587dc601f9ffa703135af59317f71d08f6",["Text"]="-----------------------------------\n-- ID: 6054\n-- Windstorm Schema\n-- Teaches the white magic Windstorm\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.WINDSTORM)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.WINDSTORM)\nend\n\nreturn itemObject\n"},["scripts/items/windurst_salad.lua"]={["Path"]="scripts/items/windurst_salad.lua",["SHA256"]="dfb7e7bb98f72c2547e238314c9905b5ae47901a9503db4f4512b58768622010",["Text"]="-----------------------------------\n-- ID: 4555\n-- Item: windurst_salad\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Magic 20\n-- Agility 5\n-- Vitality -1\n-- Ranged ACC % 8\n-- Ranged ACC Cap 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.AGI, 5)\n    effect:addMod(xi.mod.VIT, -1)\n    effect:addMod(xi.mod.FOOD_RACCP, 8)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/windurst_taco.lua"]={["Path"]="scripts/items/windurst_taco.lua",["SHA256"]="2efa17f89c7c2bf0636838ec33a90cbc2e9ffef54335319c7633d121106617b0",["Text"]="-----------------------------------\n-- ID: 5172\n-- Item: windurst_taco\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- MP 20\n-- Vitality -1\n-- Agility 5\n-- MP Recovered While Healing 1\n-- Ranged Accuracy % 8 (cap 10)\n-- Ranged Attack +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.VIT, -1)\n    effect:addMod(xi.mod.AGI, 5)\n    effect:addMod(xi.mod.MPHEAL, 1)\n    effect:addMod(xi.mod.RATT, 1)\n    effect:addMod(xi.mod.FOOD_RACCP, 8)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/windurst_waters_gate_glyph.lua"]={["Path"]="scripts/items/windurst_waters_gate_glyph.lua",["SHA256"]="02bd49a89caa4ccdef71080ac5f06c0deb6f173a227e39c9d5939792e7bb78f8",["Text"]="-----------------------------------\n-- ID: 4193\n-- Windurst Waters Gate Glyph\n-- Transports the user to the Windurst Waters gate\n-- (near Puroiko-Maiko, W.W.)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.WINDY_WATERS_GLYPH, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/windurst_woods_gate_glyph.lua"]={["Path"]="scripts/items/windurst_woods_gate_glyph.lua",["SHA256"]="cbaaf3ba2fc79a0054ac09c489c559c8a7bc76da65eeffac5250a4421d2f3c46",["Text"]="\n-----------------------------------\n-- ID: 4195\n-- Windurst Woods Gate Glyph\n-- Transports the user to the Windurst Woods gate\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.WINDY_WOODS_GLYPH, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/wing_gorget.lua"]={["Path"]="scripts/items/wing_gorget.lua",["SHA256"]="e625f57c04fceabce65614ba2e7940e9825cf2bf02fc54fd94659aef1aae216d",["Text"]="-----------------------------------\n-- ID: 13144\n-- Item: wing gorget\n-- Item Effect: gives regain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.WING_GORGET) then\n        if target:hasStatusEffect(xi.effect.REGAIN) then\n            target:messageBasic(xi.msg.basic.NO_EFFECT)\n        else\n            target:addStatusEffect(xi.effect.REGAIN, { power = 5, duration = 30, origin = user, tick = 3, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.WING_GORGET })\n        end\n    end\nend\n\nreturn itemObject\n"},["scripts/items/wing_sword.lua"]={["Path"]="scripts/items/wing_sword.lua",["SHA256"]="b4731c56d0081ae568c266233fdacb92f053b0cc860bd6c85cf1631ba8f94593",["Text"]="-----------------------------------\n-- ID: 16542\n-- Item: Wing Sword\n-- Additional effect: wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local power  = 6 + utils.clamp(dStat * 35 / 54, 0, 35) -- Linear interp\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(power, power + 3),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WIND,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/wing_sword_+1.lua"]={["Path"]="scripts/items/wing_sword_+1.lua",["SHA256"]="fb4a9aa7fa7b874a007767b0eeceaf556f7b9b526ec2167fdd47ed019e230a0b",["Text"]="-----------------------------------\n-- ID: 17637\n-- Item: Wing Sword +1\n-- Additional effect: wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local power  = 9 + utils.clamp(dStat * 35 / 54, 0, 35) -- Linear interp\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(power, power + 6),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WIND,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/winterflower.lua"]={["Path"]="scripts/items/winterflower.lua",["SHA256"]="1906b494da991dd143cfa82bf3b3196872e6a300739143e381ceed5b219428ea",["Text"]="-----------------------------------\n-- ID: 5907\n-- Item: Winterflower\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility +3\n-- Intelligence +5\n-- Charisma -5\n-- Resist Virus +20\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 3)\n    effect:addMod(xi.mod.INT, 5)\n    effect:addMod(xi.mod.CHR, -5)\n    effect:addMod(xi.mod.VIRUSRES, 20)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/witch_kabob.lua"]={["Path"]="scripts/items/witch_kabob.lua",["SHA256"]="ce40c7175ab06f92db826bb49e8b2da7cf7d62ed3046ad47f07da871927442d1",["Text"]="-----------------------------------\n-- ID: 4343\n-- Item: witch_kabob\n-- Food Effect: 1hour, All Races\n-----------------------------------\n-- Magic Points 15\n-- Mind 4\n-- Enmity -1\n-- MP Recovered While Healing 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 15)\n    effect:addMod(xi.mod.MND, 4)\n    effect:addMod(xi.mod.ENMITY, -1)\n    effect:addMod(xi.mod.MPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/withered_rolanberry.lua"]={["Path"]="scripts/items/withered_rolanberry.lua",["SHA256"]="8f9bcc8463de3305bb174975ae57cc227198d7352af3de0ff5aad62d3c6b6e5b",["Text"]="-----------------------------------\n-- ID: 5675\n-- Item: Withered Rolanberry\n-- Food Effect: 30 Mins, All Races\n-----------------------------------\n-- Intelligence 1\n-- Agility -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 1)\n    effect:addMod(xi.mod.AGI, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/wizard_cookie.lua"]={["Path"]="scripts/items/wizard_cookie.lua",["SHA256"]="2ddd0b876c4b886c2c3801727a9cfac878c933f39f5a76d847c09be437334de0",["Text"]="-----------------------------------\n-- ID: 4576\n-- Item: wizard_cookie\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- MP Recovered While Healing 7\n-- Plantoid Killer 12\n-- Slow Resist 12\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 7)\n    effect:addMod(xi.mod.PLANTOID_KILLER, 12)\n    effect:addMod(xi.mod.SLOWRES, 12)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/wonder_maillot_+1.lua"]={["Path"]="scripts/items/wonder_maillot_+1.lua",["SHA256"]="2b1b199e9487d05252c06254a3662865c793a43743bd742619c1dfd5222bdcce",["Text"]="-----------------------------------\n-- ID: 11277\n-- Item: wonder mailot +1\n-- Teleport's user to Purgonorgo Isle\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.BIBIKI_BAY) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.PURGONORGO, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/wonder_top_+1.lua"]={["Path"]="scripts/items/wonder_top_+1.lua",["SHA256"]="265fff93c5d0674efc7ad8d0dad92a800f29407ff9141db73c3ac5d42b6cf8c5",["Text"]="-----------------------------------\n-- ID: 11278\n-- Item: wonder top +1\n-- Teleport's user to Purgonorgo Isle\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.BIBIKI_BAY) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.PURGONORGO, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/woodsy_gilet_+1.lua"]={["Path"]="scripts/items/woodsy_gilet_+1.lua",["SHA256"]="33c9ce72a4cb5cd661a6efc8714f73f26ba4fa2b45780b656742a64e5d7f4d7a",["Text"]="-----------------------------------\n-- ID: 10266\n-- Woodsy Gilet +1\n-- Dispense: Berry Snowcone\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BERRY_SNOW_CONE, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/woodsy_top_+1.lua"]={["Path"]="scripts/items/woodsy_top_+1.lua",["SHA256"]="efe5930386aa01a025f9429d884e246b098feb5c751b3f57edd53c852df94ba8",["Text"]="-----------------------------------\n-- ID: 10267\n-- Woodsy Top +1\n-- Dispense: Berry Snowcone\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BERRY_SNOW_CONE, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/woozyshroom.lua"]={["Path"]="scripts/items/woozyshroom.lua",["SHA256"]="63e94aeb955add43157039642f13c44ad01bfda506ebe1eee3bf9352a5bdcb57",["Text"]="-----------------------------------\n-- ID: 4373\n-- Item: woozyshroom\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Strength -4\n-- Mind 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, -4)\n    effect:addMod(xi.mod.MND, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/worm_belt.lua"]={["Path"]="scripts/items/worm_belt.lua",["SHA256"]="131cdfbca3901867d4735d920584c150afb3d0dd84d1e79b4200b8914f334306",["Text"]="-----------------------------------\n-- ID: 15298\n-- Worm Belt\n-- Enchantment: 60Min, Costume - Worm (orange/brown)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 424, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/wyrmking_masque_+1.lua"]={["Path"]="scripts/items/wyrmking_masque_+1.lua",["SHA256"]="e0e97d6e0d4032d367527ca29be28fc7726bf375d5a0486677536c1adc0cd445",["Text"]="-----------------------------------\n-- ID: 25658\n-- Wyrmking Masque +1\n-- Dispense: Flarelet x99\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FLARELET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/wyrmking_suit_+1.lua"]={["Path"]="scripts/items/wyrmking_suit_+1.lua",["SHA256"]="9a2a17bc5f671716a61afa54fe75e2e9d379c08bf6b1618b04a2f5be283079c8",["Text"]="-----------------------------------\n-- ID: 25757\n-- Item: Wyrmking Suit +1\n-- Teleport's user to Riverne Site #B-01\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.RIVERNE_SITE_B01) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.WYRMKING_SUIT, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/x-potion.lua"]={["Path"]="scripts/items/x-potion.lua",["SHA256"]="6b38d1b483d90ded12a1aa5448a124725f1c34c4faabce96602b442c438360c3",["Text"]="-----------------------------------\n-- ID: 4120\n-- Item: X-Potion\n-- Item Effect: Restores 150 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(150 * xi.settings.main.ITEM_POWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 5, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/x-potion_+1.lua"]={["Path"]="scripts/items/x-potion_+1.lua",["SHA256"]="22ed7f6a5b433de5d507e5142a2fba78abfb986294bb59ac1d0fc378355aed48",["Text"]="-----------------------------------\n-- ID: 4121\n-- Item: X-Potion +1\n-- Item Effect: Restores 160 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(160 * xi.settings.main.ITEM_POWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 5, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/x-potion_+2.lua"]={["Path"]="scripts/items/x-potion_+2.lua",["SHA256"]="45821b3d020cf980a25c84d05139976b2d0f4cb547cf3624008a062a298126d3",["Text"]="-----------------------------------\n-- ID: 4122\n-- Item: X-Potion +2\n-- Item Effect: Restores 170 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(170 * xi.settings.main.ITEM_POWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 5, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/x-potion_+3.lua"]={["Path"]="scripts/items/x-potion_+3.lua",["SHA256"]="f13fa95d7d979a2a84ae557c1104aab37901164ae20896f8604a710a24502ba2",["Text"]="-----------------------------------\n-- ID: 4123\n-- Item: X-Potion +3\n-- Item Effect: Restores 180 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(180 * xi.settings.main.ITEM_POWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 5, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/yagudo_cherry.lua"]={["Path"]="scripts/items/yagudo_cherry.lua",["SHA256"]="95affafe59659203651c702c04ddad6e604d25ffef9f92b039d9ba851fee7787",["Text"]="-----------------------------------\n-- ID: 4445\n-- Item: yagudo_cherry\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -3\n-- Intelligence 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -3)\n    effect:addMod(xi.mod.INT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/yellow_curry_bun.lua"]={["Path"]="scripts/items/yellow_curry_bun.lua",["SHA256"]="ed90c718d78064fe0272d7dfc4bd4f847c09795bfe549a53e554d58e8447590e",["Text"]="-----------------------------------\n-- ID: 5757\n-- Item: yellow_curry_bun\n-- Food Effect: 30minutes, All Races\n-- https://wiki.ffo.jp/html/17703.html\n-----------------------------------\n-- Health Points 20\n-- Strength 5\n-- Agility 2\n-- Intelligence -4\n-- Attack 20% (caps @ 75)\n-- Ranged Attack 20% (caps @ 75)\n-- Resist Sleep +3\n-- Resist Stun +4\n-- hHP +2\n-- hMP +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nlocal dataTable =\n{\n    [ 1] = { xi.mod.FOOD_HP,       30, 25, 20 },\n    [ 2] = { xi.mod.VIT,            2,  1,  0 },\n    [ 3] = { xi.mod.AGI,            3,  3,  2 },\n    [ 4] = { xi.mod.INT,           -2, -3, -4 },\n    [ 5] = { xi.mod.FOOD_ATTP,     22, 21, 20 },\n    [ 6] = { xi.mod.FOOD_ATT_CAP,  85, 80, 75 },\n    [ 7] = { xi.mod.FOOD_RATTP,    22, 21, 20 },\n    [ 8] = { xi.mod.FOOD_RATT_CAP, 85, 80, 75 },\n    [ 9] = { xi.mod.SLEEPRES,       5,  3,  3 },\n    [10] = { xi.mod.STUNRES,        6,  4,  4 },\n    [11] = { xi.mod.HPHEAL,         6,  4,  2 },\n    [12] = { xi.mod.MPHEAL,         3,  2,  1 },\n    [13] = { xi.mod.STR,            5,  5,  5 }\n}\n\nitemObject.onEffectGain = function(target, effect)\n    for i = 1, #dataTable do\n        -- Get party factor.\n        local partySize = target:getPartySize()\n        local column = 4\n        if partySize >= 4 then\n            column = 2\n        elseif partySize >= 2 then\n            column = 3\n        end\n\n        effect:addMod(dataTable[i][1], dataTable[i][column])\n    end\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/yellow_curry_bun_+1.lua"]={["Path"]="scripts/items/yellow_curry_bun_+1.lua",["SHA256"]="74f36a2fff0cf411804dee68666e21d2a227ff116f81796b4e0b75dccfc68de2",["Text"]="-----------------------------------\n-- ID: 5763\n-- Item: yellow_curry_bun_+1\n-- Food Effect: 60 min, All Races\n-----------------------------------\n-- TODO: Group effects\n-- Health Points 30\n-- Strength 5\n-- Vitality 2\n-- Agility 3\n-- Intelligence -2\n-- Attack 22% (caps @ 85)\n-- Ranged Attack 22% (caps @ 85)\n-- Resist Sleep +5\n-- Resist Stun +6\n-- hHP +6\n-- hMP +3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 30)\n    effect:addMod(xi.mod.STR, 5)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.AGI, 3)\n    effect:addMod(xi.mod.INT, -2)\n    effect:addMod(xi.mod.FOOD_ATTP, 22)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 85)\n    effect:addMod(xi.mod.FOOD_RATTP, 22)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 85)\n    effect:addMod(xi.mod.SLEEPRES, 5)\n    effect:addMod(xi.mod.STUNRES, 6)\n    effect:addMod(xi.mod.HPHEAL, 6)\n    effect:addMod(xi.mod.MPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/yellow_drop.lua"]={["Path"]="scripts/items/yellow_drop.lua",["SHA256"]="b1ad93af409a3ab8c4e03f21c363b24c08e00079afb8467794f2e468c41c91fc",["Text"]="-----------------------------------\n--  ID: 4261\n--  Item: Yellow Drop\n--  Charisma 5\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.VIT_BOOST, { power = 5, duration = 900, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/yellow_globe.lua"]={["Path"]="scripts/items/yellow_globe.lua",["SHA256"]="20ad45116b4cc0bec3e25481bb6a798d3f20b00d9717b8f94846a72d426205be",["Text"]="-----------------------------------\n-- ID: 4403\n-- Item: yellow_globe\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/yilanbaligi.lua"]={["Path"]="scripts/items/yilanbaligi.lua",["SHA256"]="038a2ab661890fb6cf765ab980ff585cd5224381b650d06bc4686c1994331110",["Text"]="-----------------------------------\n-- ID: 5458\n-- Item: Yilanbaligi\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-- Evasion 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/yogurt_cake.lua"]={["Path"]="scripts/items/yogurt_cake.lua",["SHA256"]="a2de934f94e780e18e1ee35d6b5b362f6753dd9a7baf91ddca60b80af60cd1da",["Text"]="-----------------------------------\n-- ID: 5627\n-- Item: Yogurt Cake\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- Intelligence 1\n-- HP Recovered while healing 3\n-- MP Recovered while healing 6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 1)\n    effect:addMod(xi.mod.HPHEAL, 3)\n    effect:addMod(xi.mod.MPHEAL, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/zafmlug_bass.lua"]={["Path"]="scripts/items/zafmlug_bass.lua",["SHA256"]="8825bb54ca7865d9928d90dffd352d5b059cc6da39e96fa6d86e6a793edcacb5",["Text"]="-----------------------------------\n-- ID: 4385\n-- Item: zafmlug_bass\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/zebra_eel.lua"]={["Path"]="scripts/items/zebra_eel.lua",["SHA256"]="ef44080afa7108be11ff26ba9547583fa4c6fbd508bcabfe8e039dbd072b10ed",["Text"]="-----------------------------------\n-- ID: 4288\n-- Item: Zebra Eel\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-- Evasion 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/zegham_carrot.lua"]={["Path"]="scripts/items/zegham_carrot.lua",["SHA256"]="0107ced75349a20f1c347979914520d1a2bbd2966a492108e42555357da596bb",["Text"]="-----------------------------------\n-- ID: 5608\n-- Item: Zegham Carrot\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 2\n-- Vitality -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.VIT, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/zoolater_hat.lua"]={["Path"]="scripts/items/zoolater_hat.lua",["SHA256"]="2c05ca7df6817d3dcaaea1cfec9de85f8cb36fe65d1d15cec750314502f5a054",["Text"]="-----------------------------------\n-- ID: 15182\n-- Item: Zoolater Hat\n-- Item Effect: Pet gets meditate\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local pet = target:getPet()\n    if pet then\n        pet:addStatusEffect(xi.effect.REGAIN, { power = 15, duration = 15, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/zucchini.lua"]={["Path"]="scripts/items/zucchini.lua",["SHA256"]="c8d47956b0c35b69924e7faa2df987bcc5580221a4e3c6029fbe923e4706e7be",["Text"]="-----------------------------------\n-- ID: 5726\n-- Item: Zucchini\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 1\n-- Vitality -3\n-- Defense -1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -3)\n    effect:addMod(xi.mod.DEF, -1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"}};
